import type { MetadataRoute } from 'next'

/**
 * robots.txt — generated by Next.js App Router.
 * Allows all crawlers access to public pages.
 * Blocks admin panel, API routes, and Payload internals.
 */
export default function robots(): MetadataRoute.Robots {
  const BASE = 'https://sunkeydesignsystems.com'

  return {
    rules: [
      {
        userAgent: '*',
        allow: '/',
        disallow: [
          '/admin',
          '/admin/',
          '/api/',
          '/_next/',
        ],
      },
    ],
    sitemap:    `${BASE}/sitemap.xml`,
    host:       BASE,
  }
}
